interface Calculator {
    static int multiply(int a, int b) { return a * b; }
    default int add(int a, int b) { return a + b + helper(); }
    private int helper() { return 5; }
}

class BasicCalculator implements Calculator {}

public class Test {
    public static void main(String[] args) {
        BasicCalculator calc = new BasicCalculator();
        System.out.print(Calculator.multiply(2, 3) + " ");
        System.out.print(calc.multiply(2, 3));
    }
}

interface Payable {
    double getPaymentAmount();
}

class Invoice implements Payable {
    public double getPaymentAmount() { return 150.0; }
    public String getVendor() { return "VendorCorp"; }
}

public class Test {
    public static void main(String[] args) {
        Payable[] payables = { new Invoice() };
        for (Payable p : payables) {
            System.out.print(p.getClass().getSimpleName() + " ");
            System.out.print(((Invoice) p).getVendor() + " ");
            System.out.print(p.getVendor());
        }
    }
}
